    # Define the load_data function to read each line of the carprice.txt file and load into a dictionary called price.
    def load_data(self, file_name):
        try:
            # Create an empty dictionary called price.
            price = {}
            # Read each line of the carprice.txt file.
            with open(file_name, "r") as fname:
                for line in fname:
                    # strip() will remove extra whitespaces before and after the text.
                    # split() will split the data based on the delimiter of ",".
                    car_type, car_price = line.strip().split(",")
                    # Add a new key value pair to the dictionary.
                    price[car_type] = int(car_price)
            return price
            
        # Specific exception block to handle file not found error
        except FileNotFoundError:
            print("The file does not exist")
        # Generic exception block for all other unexpected errors
        except Exception as e:
            print(e)
    
    # Define the purchases_made function to accept all user inputs and the write the data to an external file called purchases_made.txt.
    def purchase_made(self):
        try:
            # Get the customer's Name and store it in the name variable.
            name = self.txtName.text()
            # Get the customer's Age and store it in the age variable.
            age = self.txtAge.text()
            # Get the customer's Down Payment and store it in the down_payment variable.
            down_payment = self.txtDownPayment.text()
            # Get the customer's Car Selection and store it in the current_selection variable.
            current_selection = self.cmbSelection.currentText()
            
            # Get the customer's Choice of Model and store it in the model variable.
            # If the Basic radio button is selected, set the model variable to Basic.
            if(self.rdBasic.isChecked()):
                model = "Basic"
            # If the Hybrid radio button is selected, set the model variable to Hybrid.
            elif(self.rdHybrid.isChecked()):
                model = "Hybrid"
            # If the Sport radio button is selected, set the model variable to Sport.
            elif(self.rdSport.isChecked()):
                model = "Sport"
            # If a radio button is not selected, set the model variable to Not Selected.
            else:
                model = "Not Selected" 
            
            # Validate the user has entered the Name as letters, has entered the Age and Down Payment as numbers, and selected a Model Choice.
            if(name.isalpha() and age.isdigit() and down_payment.isdigit() and model != "Not Selected"):
                
                # Write the user inputs to a new line in the purchases_made.txt file.
                with open("purchases_made.txt", "a") as fname:
                    fname.write(name+",  "+age+",  "+current_selection+",  "+model+",  "+down_payment+"\n")
            
            else:
                # Display an error message to the user if the Name, Age, Down Payment, or model choice is not filled in.
                msg = QtWidgets.QMessageBox()
                # Set the title of the Message Box to Car Financing.
                msg.setWindowTitle("Car Financing")
                # Set the display text of the Message Box.
                msg.setText("Please enter valid inputs for the Name, Age, and Down Payment and select a Model Choice.")
                # Execute the Message Box
                msg.exec()
            
        # Generic exception block for all other unexpected errors 
        except Exception as e:
            print(e)
    
    # Define the show_payments function to calculate the monthly payments and display the data in a list box on the Car Purchase tab.
    def show_payments(self):
        try:
            # Define the total_price variable and set it to 0.
            total_price = 0
            # Define the loan_amount variable and set it to 0.
            loan_amount = 0
            # Define the annual_rate variable and set it to 0.06.
            annual_rate = 0.06
            # Define and calculate and the monthly_rate variable.
            monthly_rate = annual_rate/12
            # Define the loan_term variable and set it to 60 months.
            loan_term = 60
            # Define the loan_term_months variable and set it to 0.
            loan_term_months = 1
            # Define the monthly_payment variable and set it to 0.
            monthly_payment = 0
            # Get the customer's Car Selection and store it in the current_selection variable.
            current_selection = self.cmbSelection.currentText()
            # Get the customer's Down Payment and store it in the down_payment variable.
            down_payment = self.txtDownPayment.text()
            
            # Get the price of the car from the price dictionary based on the current_selection variable.
            total_price = self.price_dictionary.get(current_selection)
            
            # Get the customer's Choice of Model and store it in the model variable.
            # If the Basic radio button is selected, set the model variable to Basic.
            if(self.rdBasic.isChecked()):
                model = "Basic"
            # If the Hybrid radio button is selected, set the model variable to Hybrid.
            elif(self.rdHybrid.isChecked()):
                model = "Hybrid"
            # If the Sport radio button is selected, set the model variable to Sport.
            elif(self.rdSport.isChecked()):
                model = "Sport"
            # If a radio button is not selected, set the model variable to Not Selected.
            else:
                model = "Not Selected" 
                
            # Validate the user has entered the Down Payment as a number and selected a Model Choice.
            if(down_payment.isdigit() and model != "Not Selected"):
                
                # Calculate the total_price variable based on the customer's Choice of Model.
                # If the Hybrid radio button is checked, add 20% to the car price from the price dictionary.
                if(self.rdHybrid.isChecked()):
                    total_price = total_price * 1.20
                # If the Sport radio button is checked, add 30% to the car price from the price dictionary.
                elif(self.rdSport.isChecked()):
                    total_price = total_price * 1.30
                # If the Basic radio button or no button is checked, make no changes to the total_price variable.
                else:
                    total_price = total_price + 0
            
                # Convert the down_payment variable from text to an integer value.
                down_payment = int(down_payment)
                # Calculate the loan_amount variable by subtracting the down_payment from the loan_amount.
                loan_amount = total_price - down_payment
                # Calculate the monthly_payment.
                monthly_payment = (loan_amount * monthly_rate * ((1 + monthly_rate) ** loan_term)) / ((1 + monthly_rate) ** loan_term - 1)
                # Create the currency_payment variable as a formatted version of the monthly_payment variable.
                currency_payment = f"${monthly_payment:,.2f}"
            
                # Write column headings to the Monthly Payments list box on the Car Purchase tab.
                self.lstPayments.addItem("Month          Payment          Remaining Balance")
            
                # For each month leading up to the loan_term, calculate and display the monthly payments in the list box on the Car Purchase tab.
                for each_month in range(1, loan_term + 1):
                    # Update the loan_amount to represent the remaining loan balance by subtracting the portion of the monthly payment that is for principal.
                    loan_amount = loan_amount - (monthly_payment - (loan_amount * monthly_rate))
                    # Create the currency_balance variable as a formatted version of the loan_amount variable.
                    currency_balance = f"${loan_amount:,.2f}"
                    # Write the month number, monthly payment, and remaining loan balance to the list box on the Card Purchase tab.
                    self.lstPayments.addItem(str(loan_term_months)+"               "+currency_payment+"               "+currency_balance)
                    # Increment the loan_term_months variable by 1 month.
                    loan_term_months = loan_term_months + 1
                    # Break statement to exit the loop if the loan_amount < 0.
                    if(loan_amount < 0):
                        break
            
            else:
                # Display an error message to the user if the Down Payment or Model Choice is not filled in.
                msg = QtWidgets.QMessageBox()
                # Set the title of the Message Box to Car Financing.
                msg.setWindowTitle("Car Financing")
                # Set the display text of the Message Box.
                msg.setText("Please enter valid inputs for the Down Payment and select a Model Choice.")
                # Execute the Message Box
                msg.exec()
            
        # Generic exception block for all other unexpected errors        
        except Exception as e:
            print(e)
                        
    # Define the clear function that resets all fields to their default values when the Clear button is clicked.
    def clear(self):
        try:
            # Clears the Name text box.
            self.txtName.clear()
            # Clears the Age text box.
            self.txtAge.clear()
            # Re-set the Car Selection combo box to Sonata.
            self.cmbSelection.setCurrentIndex(0)
            # Re-set the Model Type radio button to Basic.
            self.rdBasic.setChecked(True)
            # Clears the Down Payment text box.
            self.txtDownPayment.clear()
            # Clear the Show Payments list box.
            self.lstPayments.clear()
        
        # Generic exception block for all other unexpected errors
        except Exception as e:
            print(e)
            
