    # Define the display_data function to read the data from the purchases_made.txt file and display
    # each line in the list box on the Purchases Made tab.
    def display_data(self, index):
        try:
            # Clear the data on the Purchases Made tab if user clicks on the Car Purchase tab.
            if(index == 0):
                self.lstPurchasesMade.clear()
            # Read each line of the purchases_made.txt file and display each line in the list box on the
            # Purchases Made tab.
            else:                
                with open("purchases_made.txt", "r") as fname:
                    for line in fname:
                        self.lstPurchasesMade.addItem(line)
        
        # Specific exception block to handle file not found error
        except FileNotFoundError:
            print("No purchase data exists")
        
        # Generic exception block for all other unexpected errors
        except Exception as e:
            print(e) 
            
